import data from "./labels.json";

/**
 * District / region / water labels drawn over the map (zoom-dependent text, not pins).
 *
 * DATA RULE: names come only from official Rockstar material. Every entry records the page and wording in labels.json
 * (`sourceUrl`, `sourceQuote`); where a district's direction came from GTADB.org (CC BY 4.0) that is in `placement` and
 * credited in docs/DATA_CREDITS.md. The file is generated by scripts/art/build_labels.py.
 *
 * x/y are stored pin coordinates (COORD_SPACE), so labels follow whichever base is showing, exactly like pins do.
 * `anchor` is the id of a seed pin whose fixed art position the label shares.
 */
export type LabelKind = "region" | "district" | "place" | "water";

export interface MapLabel {
  id: string;
  name: string;
  kind: LabelKind;
  x: number;
  y: number;
  anchor?: string;
  /** Absolute map zoom from which the label may appear (regions ignore it: they take over when the region chips fade). */
  minZoom: number;
  approximate: boolean;
  source: "official";
  sourceUrl: string;
  sourceQuote: string;
  placement: string;
}

export const LABELS: MapLabel[] = data.labels as MapLabel[];

/** Drawing priority when labels collide: lower wins. */
export const LABEL_PRIORITY: Record<LabelKind, number> = { region: 0, water: 1, district: 2, place: 3 };
